  "preferred_configuration": {
    "prize_parts": [
      {
        "ballot_id": "B031",
        "laureates": [
          "Hidetoshi Katori",
          "Jun Ye"
        ],
        "citation": "For the invention and development of optical lattice clocks."
      }
    ]
  },
  "alternatives": [
    "B009",
    "B008"
  ],
  "statement": {
    "case_for": "Optical lattice clocks use carefully chosen atomic transitions and confinement in an optical lattice to suppress motion-related frequency shifts. This made optical frequencies usable as exceptionally stable references, opening a new regime of precision measurement and tests of fundamental physics. Katori and Ye established complementary approaches, and independent implementations and continuing experimental refinement give the achievement a strong, reproducible foundation.",
    "case_against": "The clock's present performance is the result of sustained work by a broad community. The committee would need to distinguish the original conceptual and experimental contributions from later improvements, and make clear why these two contributions define the prize-worthy advance.",
    "responses": [
      {
        "member_id": "kroll-stefan",
        "point": "Kroll supports Katori and Ye, while noting that the boundary between the foundational clock invention and subsequent precision advances may be difficult to delimit.",
        "response": "I agree that the citation should stay focused on establishing the optical lattice clock approach, rather than claiming credit for every later performance improvement or application. That boundary is important, but it does not erase the distinct foundational contributions represented by Katori and Ye."
      },
      {
        "member_id": "johansson-goran",
        "point": "Johansson emphasizes independent, reproducible implementations and the clock's maturity, while asking how the international community's contributions should affect the attribution.",
        "response": "The wide adoption is evidence that the principle is robust, but it also means later improvements should not be folded into the laureates' claim. I would credit the complementary approaches that established the field and acknowledge the wider community through a tightly framed citation."
      }
    ],
    "uncertainties": [
      "The historical boundary between the original clock concepts and later advances that enabled today's accuracy needs careful review."
    ],
    "conflict_note": "No profile-based connection to the proposed laureates or this achievement is apparent."
  }
}
